package com.example.jobfinderapp.models;
public class Certificate { private int id,userId; private String certificateName,organization,issueDate,expiryDate,credentialId,credentialUrl; public int getId(){return id;}public void setId(int v){id=v;}public int getUserId(){return userId;}public void setUserId(int v){userId=v;}public String getCertificateName(){return certificateName;}public void setCertificateName(String v){certificateName=v;}public String getOrganization(){return organization;}public void setOrganization(String v){organization=v;}public String getIssueDate(){return issueDate;}public void setIssueDate(String v){issueDate=v;}public String getExpiryDate(){return expiryDate;}public void setExpiryDate(String v){expiryDate=v;}public String getCredentialId(){return credentialId;}public void setCredentialId(String v){credentialId=v;}public String getCredentialUrl(){return credentialUrl;}public void setCredentialUrl(String v){credentialUrl=v;} }
